CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE TYPE identifier_type AS ENUM ('RUT','PASSPORT','NATIONAL_ID','INTERNAL','OTHER');
CREATE TYPE conversion_status AS ENUM ('QUEUED','PROCESSING','READY','REVIEW','FAILED');
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), email citext UNIQUE NOT NULL, password_hash text NOT NULL, full_name text NOT NULL, role text NOT NULL DEFAULT 'operator', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS password_resets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE IF NOT EXISTS patients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), given_names text, family_names text, birth_date date, sex text, identifier_type identifier_type NOT NULL DEFAULT 'INTERNAL', identifier_value text NOT NULL, rut_normalized text, email text, phone text, address jsonb NOT NULL DEFAULT '{}', cmbd jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), archived_at timestamptz, UNIQUE(organization_id, identifier_type, identifier_value));
CREATE TABLE IF NOT EXISTS studies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id), study_instance_uid text UNIQUE NOT NULL, accession_number text, modality text, description text, study_date date, referring_physician text, status text NOT NULL DEFAULT 'active', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), study_id uuid REFERENCES studies(id), patient_id uuid REFERENCES patients(id), batch_id uuid NOT NULL, original_name text NOT NULL, original_mime text, source_sha256 text NOT NULL, source_path text NOT NULL, dicom_path text, sop_instance_uid text, status conversion_status NOT NULL DEFAULT 'QUEUED', error_message text, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid REFERENCES patients(id), title text NOT NULL, category text, version integer NOT NULL DEFAULT 1, storage_path text NOT NULL, mime_type text, tags text[] NOT NULL DEFAULT '{}', retention_until date, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS crm_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), patient_id uuid REFERENCES patients(id), type text NOT NULL, subject text NOT NULL, status text NOT NULL DEFAULT 'open', owner_id uuid REFERENCES users(id), next_action_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, organization_id uuid, actor_id uuid, action text NOT NULL, entity_type text NOT NULL, entity_id text, ip inet, user_agent text, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS patients_search_idx ON patients (organization_id, identifier_value);
CREATE INDEX IF NOT EXISTS conversions_batch_idx ON conversions (batch_id, status);
CREATE INDEX IF NOT EXISTS audit_entity_idx ON audit_log (entity_type, entity_id, created_at DESC);
